def algorithm(func, dim, lb, ub, budget, rng):
    x_best = rng.uniform(lb, ub, dim)
    for _ in range(budget):
        x_new = x_best + rng.normal(size=dim) * 0.01
        x_new = np.clip(x_new, lb, ub)
        f_new = func(x_new)
        if f_new < func(x_best):
            x_best = x_new
    return x_best

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def accept(current, candidate, T):
        if func(candidate) < func(current):
            return candidate
        else:
            p = np.exp(-(func(candidate) - func(current)) / (T * 1e-3))
            if rng.random() < p:
                return candidate
            else:
                return current

    current_best = np.zeros(dim)
    T = ub - lb + 1
    for _ in range(budget):
        candidate = clip(np.array(rng.uniform(lb, ub, size=dim)))
        current_best = accept(current_best, candidate, T)
        T *= 0.99
    return current_best
